    const byFac = new Map<string, { name: string; tax: number; claim: number; n: number; type?: string }>(); for (const r of st.rows) { const o = outs.get(r.id)!; const a = assignOf(r).a; const id = a?.fid ?? 'none'; const nm = id === 'admin' ? '본청·행정 공통' : id === 'exempt' ? '면세·행정 전용' : id === 'none' ? '미지정' : (o.f?.name ?? id); const b = byFac.get(id) ?? { name: nm, tax: 0, claim: 0, n: 0, type: o.f?.type }; b.tax += r.tax; b.claim += o.claim; b.n++; byFac.set(id, b); }
